), geometries AS MATERIALIZED (
    SELECT
        kod,
        nazev,
        ST_SetSRID(ST_GeomFromGeoJSON(geojson), 4326)::geometry(Polygon, 4326) AS boundary
    FROM source_data
), resolved AS MATERIALIZED (
    SELECT kod, nazev, boundary, ST_PointOnSurface(boundary) AS reference_point
    FROM geometries
), inserted AS (
    INSERT INTO public."ZSJ" (kod, nazev, lat, lon, boundary)
    SELECT
        kod,
        nazev,
        ST_Y(reference_point)::double precision AS lat,
        ST_X(reference_point)::double precision AS lon,
        boundary
    FROM resolved
    ON CONFLICT (kod) DO NOTHING
    RETURNING kod
)
SELECT COUNT(*) AS vlozeno_zsj FROM inserted;

CREATE INDEX IF NOT EXISTS zsj_boundary_gist_idx
    ON public."ZSJ" USING gist (boundary);

COMMIT;
